We found, however, that instead of updating $B$ by (\ref{eq:B}) at each iteration, handling $B$ as a parameter to be controlled in the outer loop, in conjunction with modifying (\ref{BPnaive1}) and (\ref{BPnaive2}) to 
\begin{eqnarray}
\hat{a}_\mu &=& \hat{a}_\mu -\frac{1}{B} f^{\prime}\left (\sum_{i=1}^N \Phi_{\mu i} \hat{x}_i  \right ), \end{eqnarray}
results in a fairly good approximate signal recovery algorithm.

Averaging (\ref{eq:expansion}) with respect to $\vm{\Phi}$ and $\vm{x}^0$ offers the following expression of the $n$-th moment of the partition function:
\begin{eqnarray}
&&\left[Z^{n}\left(\beta; \Phi, \textrm{\boldmath $x$}^{0}\right)\right]_{\Phi,\textrm{\boldmath $x$}^{0}}=
\int 
\prod_{a=1}^n \left (d \textrm{\boldmath $x$}^a\delta\left(\vert \textrm{\boldmath $x$}^a\vert^{2}-N\right) \times 
e^{-\beta||\textrm{\boldmath $x^a$}||_{1}} \right ) \cr
&& \hspace*{3cm} \times 
\left[\prod_{a=1}^n \prod_{\mu=1}^M 
\Theta\left(
(\vm{\Phi} \vm{x}^0)_\mu 
(\vm{\Phi} \vm{x}^a)_\mu 
\right)
\right]_{\vm{\Phi},\vm{x}^{0}}. \end{eqnarray}
We insert $n(n+1)/2$ trivial identities
\begin{eqnarray}
1=N \int dq_{ab} \delta \left (\vm{x}^a \cdot \vm{x}^b - N q_{ab} \right ), 
\end{eqnarray}
where $a>b=0,1,2,\ldots,n$, into (\ref{Zmoment}). Furthermore, we define a joint distribution of $n+1$ vectors $\{\vm{x}^a\}=\{\vm{x}^0, \vm{x}^1,\vm{x}^2,\ldots,\vm{x}^n \}$ as
\begin{eqnarray}
&&P\left (\{\vm{x}^a\} |\vm{Q}\right )= \frac{1}{V\left (\vm{Q}\right ) } P(\vm{x}^0) \times 
\prod_{a=1}^n \left (\delta \left (\left |\vm{x}^a\right |^2 -N \right ) 
\times 
e^{-\beta||\textrm{\boldmath $x^a$}||_{1}} \right )  \cr
&& \hspace*{3cm} \times \prod_{a>b} \delta \left (\vm{x}^a \cdot \vm{x}^b - N q_{ab} \right ), \end{eqnarray}
where $\vm{Q}=(q_{ab})$ is an $(n+1) \times (n+1)$ symmetric matrix whose $00$ and the other diagonal entries are fixed as $\rho$ and $1$, respectively. $P(\vm{x}^0)=\prod_{i=1}^N \left ((1-\rho)\delta(x_i^0)+\rho \tilde{P}(x_i^0) \right )$ denotes the distribution of the original signal $\vm{x}^0$, and $V\left (\vm{Q}\right )$ is the normalization constant that makes $\int \prod_{a=0}^n d \vm{x}^a P\left (\{\vm{x}^a\} |\vm{Q}\right )=1$ hold. These indicate that (\ref{Zmoment}) can also be expressed as
\begin{eqnarray}
\left[Z^{n}\left(\beta; \Phi, \textrm{\boldmath $x$}^{0}\right)\right]_{\Phi,\textrm{\boldmath $x$}^{0}}
=\int d\vm{Q} \left (V\left (\vm{Q}\right ) \times \Xi\left (\vm{Q}\right ) \right ), \end{eqnarray}
where $d\vm{Q} \equiv \prod_{a>b}d q_{ab}$ and 
\begin{eqnarray}
\Xi\left (\vm{Q}\right )
=\int \prod_{a=0}^n d\vm{x}^a P\left (\{\vm{x}^a\} |\vm{Q} \right ) 
\left[\prod_{a=1}^n \prod_{\mu=1}^M 
\Theta\left(
(\vm{\Phi} \vm{x}^0)_\mu 
(\vm{\Phi} \vm{x}^a)_\mu 
\right)
\right]_{\vm{\Phi}}. \end{eqnarray}

Equation (\ref{Xi}) can be regarded as the average of $\prod_{a=1}^n \prod_{\mu=1}^M \Theta\left((\vm{\Phi} \vm{x}^0)_\mu (\vm{\Phi} \vm{x}^a)_\mu \right)$ with respect to $\{\vm{x}^a\}$ and $\vm{\Phi}$ over distributions of $P\left (\{\vm{x}^a\} \right )$ and $P(\vm{\Phi}) \equiv \left (\sqrt{2\pi/N} \right )^{-MN} \exp \left (-(N/2) \sum_{\mu,i} \Phi_{\mu i}^2 \right )$. In computing this, it is noteworthy that the central limit theorem guarantees that $u_\mu^a \equiv (\vm{\Phi} \vm{x}^a)_\mu = \sum_{i=1}^N \Phi_{\mu i} x_i^a$ can be handled as zero-mean multivariate Gaussian random numbers whose variance and covariance are provided by 
\begin{eqnarray}
\left [u_\mu^a u_\nu^b \right ]_{\vm{\Phi},\{\vm{x}^a\}}
=\delta_{\mu \nu} q_{ab}, 
\end{eqnarray}
when $\vm{\Phi}$ and $\{\vm{x}^a\}$ are generated independently from $P(\vm{\Phi})$ and $P\left (\{\vm{x}^a\} \right )$, respectively. This means that (\ref{Xi}) can be evaluated as
\begin{eqnarray}
\Xi(\vm{Q}) &=&\left (\frac{\int d \vm{u} \exp\left (-\frac{1}{2}\vm{u}^{\rm T} \vm{Q}^{-1} \vm{u} \right )
\prod_{a=1}^n \Theta\left (u^0 u^a \right )  }{
(2\pi)^{(n+1)/2} (\det \vm{Q})^{1/2}}
\right )^M \cr
&=& \left (2 \int \frac{ d \vm{u}\exp\left (-\frac{1}{2}\vm{u}^{\rm T} \vm{Q}^{-1} \vm{u} \right )
\Theta\left (u^0 \right )\prod_{a=1}^n \Theta\left (u^a \right )  }{
(2\pi)^{(n+1)/2} (\det \vm{Q})^{1/2}}
 \right )^M. \end{eqnarray}

On the other hand, expressions 
\begin{eqnarray}
\delta\left (|\vm{x}^a|^2-N \right )
=\frac{1}{4 \pi} \int_{-{\rm i}\infty}^{+{\rm i}\infty}
d \hat{q}_{aa} \exp \left (-\frac{1}{2} \hat{q}_{aa} 
\left (|\vm{x}^a|^2-N \right ) \right )
\end{eqnarray}
and 
\begin{eqnarray}
\delta\left (\vm{x}^a \cdot \vm{x}^b -N q_{ab}\right )
=\frac{1}{2 \pi} \int_{-{\rm i}\infty}^{+{\rm i}\infty}
d \hat{q}_{ab} \exp \left ( \hat{q}_{ab} 
\left (\vm{x}^a \cdot \vm{x}^b-N q_{ab} \right ) \right ), 
\end{eqnarray}
and use of the saddle point method offer 
\begin{eqnarray}
&&\frac{1}{N} \ln V(\vm{Q})
=\mathop{\rm extr}_{\hat{\vm{Q}}}
\left \{
-\frac{1}{2} {\rm Tr} \hat{\vm{Q}}\vm{Q} \right . \cr
&& \hspace*{2cm}
\left . + \ln 
\left (
\int d\vm{x} 
P(x^0) \exp \left (\frac{1}{2} 
\vm{x}^{\rm T} \hat{\vm{Q} }\vm{x}-\beta \sum_{a=1}^n \beta |x^a| \right )
\right ) 
\right \}. \end{eqnarray}
Here $\vm{x}=(x^0,x^1,\ldots,x^n)^{\rm T}$ and $\hat{\vm{Q}}$ is an $(n+1)\times (n+1)$ symmetric matrix whose $00$ and other diagonal components are given as $0$ and $-\hat{q}_{aa}$, respectively, while off-diagonal entries are offered as $\hat{q}_{ab}$. Equations (\ref{logXi}) and (\ref{logV}) indicate that $N^{-1} \ln \left [Z^n (\beta;\vm{\Phi}, \vm{x}^0 ) \right]_{\vm{\Phi}, \vm{x}^0}$ is correctly evaluated by using the saddle point method with respect to $\vm{Q}$ in the assessment of the right-hand side of (\ref{Zn}) when $N$ and $M$ tend to infinity keeping $\alpha=M/N$ finite.

The 1-step replica symmetry breaking (1RSB) ansatz means that, at the relevant saddle point, $n$ replica indices $1,2,\ldots,n$ are classified into $n/p$ groups of an equal size $p$, and $q_{ab}=q_1$ holds if $a$ and $b$ belong to an identical group and $q_0(\le q_1)$, otherwise. This yields the following expression of the average free energy of finite temperature:
\begin{eqnarray}
&&\overline{f}=\mathop{\rm extr}_{\omega}\left \{
-\frac{1}{\beta  } \left [ \ln \left (\int {\rm D}{t}
\exp \left (-p {\cal Y}_0 \right )
\right ) \right ]_{x^0,z} \right  . \cr
&& 
\hspace*{0cm}-\frac{1}{2\beta}(\hat{Q}+\hat{q}_1)+\frac{\hat{q}_1}{2\beta} (1-q_1)+\frac{p}{2\beta}
(\hat{q}_1q_1-\hat{q}_0q_0 )+\frac{1}{\beta}\hat{m}m\cr
&&
\hspace*{0cm}\left . 
-\frac{2\alpha}{\beta p}\!
\int \! {\rm D}z H\left (\!\frac{m }{\sqrt{\rho q-m^2}}z\! \right )
\ln \left (\int {\rm D}t \exp \left (-p {\cal Y}_1 \right ) \right )
\right \}, \end{eqnarray}
where ${\cal Y}_0\equiv -\ln \left (\int dx \exp \left (-(\hat{Q}+\hat{q}_1)x^2 /2 + (\sqrt{\hat{q}_1-\hat{q}_0}t+\sqrt{\hat{q}_0}z +\hat{m}x^0 )x-\beta |x| \right ) \right )$, ${\cal Y}_1\equiv - \ln \left (\int {\rm D}x \Theta\left (-\left (\sqrt{1-q_1}x+\sqrt{q_1-q_0}t+\sqrt{q}_0 z \right ) \right ) \right )$, $\omega=\{q_1,q_0,m,\hat{Q},\hat{q}_1, \hat{q}_0, \hat{m} \}$, and $\left [\cdots \right]_{x^0,z}=\int dx^0 P(x^0)\int {\rm D}z \left (\cdots \right )$. The RS solution is regarded as a special case of the 1RSB solution for which $q_1=q_0 $ holds. Therefore one can check the thermodynamical validity of the RS solution by examining the stability of the solution of $q_1=q_0$ under the 1RSB ansatz. 

The extremization condition of (\ref{1RSB}) indicates that 
\begin{eqnarray}
&&q_1-q_0=\left [ \frac{\int {\rm D}t e^{-p {\cal Y}_0}
\left (\partial{\cal Y}_0/\partial (\sqrt{\hat{q}_0} z) \right )^2}
{\int {\rm D}t e^{-p {\cal Y}_0}} \right . \cr
&&\hspace*{4cm} \left . -
\left (\frac{\int {\rm D}t e^{-p {\cal Y}_0}
\left (\partial{\cal Y}_0/\partial (\sqrt{\hat{q}_0} z)  \right )}
{\int {\rm D}t e^{-p {\cal Y}_0}} 
\right )^2 \right ]_{x^0,z} \cr
&&\phantom{q_1-q_0} \simeq \left [ \left (\frac{\partial^2 {\cal Y}_0^{\rm RS}}{\partial (\sqrt{\hat{q}_0}z )^2} \right )^2 
\left (\frac{\int {\rm D}t e^{-p {\cal Y}_0} t^2}{\int {\rm D}t e^{-p {\cal Y}_0}}
-\left (\frac{\int {\rm D}t e^{-p {\cal Y}_0} t}{\int {\rm D}t e^{-p {\cal Y}_0}} \right )^2  \right )\right ]_{x^0,z} (\hat{q}_1-\hat{q}_0) \cr
&&\phantom{q_1-q_0} \simeq \left [ \left (\frac{\partial^2 {\cal Y}_0^{\rm RS}}{\partial (\sqrt{\hat{q}_0}z )^2} \right )^2 
\right ]_{x^0,z} (\hat{q}_1-\hat{q}_0) \end{eqnarray}
and 
\begin{eqnarray}
&&\hat{q}_1-\hat{q}_0=2 \alpha \int {\rm D}z H\left (\frac{m}{\sqrt{\rho q-m^2}}z \right )
\left ( \frac{\int {\rm D}t e^{-p{\cal Y}_1} \left (
\partial{\cal Y}_1/\partial (\sqrt{{q}_0} z) \right )^2}
{\int {\rm D}t e^{-p {\cal Y}_1}} \right . \cr
&&\hspace*{4cm} \left . -
\left (\frac{\int {\rm D}t e^{-p {\cal Y}_1}
\left (\partial{\cal Y}_1/\partial (\sqrt{{q}_0} z)  \right )}
{\int {\rm D}t e^{-p {\cal Y}_1}} 
\right )^2 \right ) \cr
&&\phantom{\hat{q}_1-\hat{q}_0} \simeq 
2 \alpha \int {\rm D}z H\left (\frac{m}{\sqrt{\rho q-m^2}}z \right )
\left (\frac{\partial^2 {\cal Y}_1^{\rm RS}}{\partial (\sqrt{{q}_0}z )^2} \right )^2\cr
&& \hspace*{4cm} 
\times \left (\frac{\int {\rm D}t e^{-p {\cal Y}_1} t^2}{\int {\rm D}t e^{-p {\cal Y}_1}}
-\left (\frac{\int {\rm D}t e^{-p {\cal Y}_1} t}{\int {\rm D}t e^{-p {\cal Y}_1}} \right )^2  \right )
(q_1-q_0)\cr
&&\phantom{\hat{q}_1-\hat{q}_0} \simeq 
2 \alpha \int {\rm D}z H\left (\frac{m}{\sqrt{\rho q-m^2}}z \right )
\left (\frac{\partial^2 {\cal Y}_1^{\rm RS}}{\partial (\sqrt{{q}_0}z )^2} \right )^2 (q_1-q_0) \end{eqnarray}
hold for $|q_1-q_0| \ll 1$ and $|\hat{q}_1-\hat{q}_0| \ll 1$ irrespectively of the value of $p$. Here ${\cal Y}_0^{\rm RS}$ and ${\cal Y}_1^{\rm RS}$ represent assessments of ${\cal Y}_0$ and ${\cal Y}_1$ under the assumptions of $\hat{q}_1=\hat{q}_0$ and $q_1=q_0$, respectively. In (\ref{AT1}) and (\ref{AT2}) we used the Taylor expansion expressions $\partial{\cal Y}_0/\partial (\sqrt{\hat{q}_0} z) \sim \partial{\cal Y}_0^{\rm RS} /\partial (\sqrt{\hat{q}_0} z) + \partial^2{\cal Y}_0^{\rm RS} /\partial (\sqrt{\hat{q}_0} z)^2 \sqrt{\hat{q}_1-\hat{q}_0} t$ and $\partial{\cal Y}_1/\partial (\sqrt{{q}_0} z) \sim \partial{\cal Y}_1^{\rm RS} /\partial (\sqrt{{q}_0} z) + \partial^2{\cal Y}_1^{\rm RS} /\partial (\sqrt{{q}_0} z)^2 \sqrt{q_1-q_0} t$, and the fact that the variances of $t$ for the measures ${\rm D}te^{-p {\cal Y}_0}/\int {\rm D}te^{-p {\cal Y}_0}$ and ${\rm D}te^{-p {\cal Y}_1}/\int {\rm D}te^{-p {\cal Y}_1}$ become unity as $\hat{q}_1 - \hat{q}_0$ and $q_1 -q_0$ vanish, irrespectively of the value of $p$.

To examine the stability of the RS solution in the limit of $\beta \to \infty$, let us change the variable notations as $\chi=\beta(1-q)$, $\hat{Q}+\hat{q}_1 \to \beta \hat{Q}$, $\hat{q}_1\to \beta^2 \hat{q}_1$, $\hat{q}_0 \to \beta^2 \hat{q}_0$, and $\hat{m}\to \beta \hat{m}$ and set $q_0=q$ and $\hat{q}_0=\hat{q}$. This yields expressions of ${\cal Y}^{\rm RS}_0 \simeq \beta \phi(\sqrt{\hat{q}}z+\hat{m}x^0; \hat{Q}) = -\beta g(\sqrt{\hat{q}}z+\hat{m}x^0)/\hat{Q}$ and ${\cal Y}_1^{\rm RS} \simeq (\beta/\chi) f(-\sqrt{q}z )$ for $\beta \gg 1$. Substituting these into (\ref{AT1}) and (\ref{AT2}) leads to 
\begin{eqnarray}
\Delta \simeq  \frac{1}{\hat{Q}^2} 
\left [ \left ( g^{\rm \prime \prime}(\sqrt{\hat{q}}z+\hat{m}x^0) \right )^2  \right ]_{x^0,z}
\hat{\Delta} \end{eqnarray}
and
\begin{eqnarray}
\hat{\Delta} \simeq  \frac{2\alpha}{\chi^2}
\int {\rm D}z H \left (\frac{m}{\sqrt{\rho-m^2}} z\right )
\left ( f^{\prime \prime} (-z) \right )^2 \Delta, \end{eqnarray}
where we set $\Delta=q_1-q$ and $\hat{\Delta}=\hat{q}_1-\hat{q}$, and used $q\to 1$. The condition that (\ref{AT1new}) and (\ref{AT2new}) allow a solution of $(\Delta,\hat{\Delta}) \ne (0,0)$ offers (\ref{AT}).

